        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                close = float(data.Bars[symbol].Close)

                if symbol == self.spy:
                    self.spy_closes.Add(close)

                elif symbol == self.aapl:
                    if self.aapl_closes.Count > 0:
                        if close < self.aapl_closes[0]:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0

                    self.aapl_closes.Add(close)
                    self.aapl_rsi.Update(
                        IndicatorDataPoint(symbol, self.Time, close)
                    )

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if self.spy_closes.Count < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
