class PrivateLotStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](15)

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        present = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                present[ticker] = data.Bars[symbol]

        # Market-state quantities continue updating whenever their own bars exist.
        if "SPY" in present:
            self.spy_closes.Add(present["SPY"].Close)

        if "AAPL" in present:
            aapl_close = present["AAPL"].Close
            self.aapl_closes.Add(aapl_close)
            self.aapl_rsi.Update(self.Time, aapl_close)

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if len(present) != len(self.symbols):
            return

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self.spy_closes.IsReady:
            today_close = self.spy_closes[0]
            yesterday_close = self.spy_closes[1]
            today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
            yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

            if yesterday_close >= yesterday_sma and today_close < today_sma:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.spy_closes.IsReady:
            today_close = self.spy_closes[0]
            yesterday_close = self.spy_closes[1]
            today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
            yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

            if yesterday_close <= yesterday_sma and today_close > today_sma:
                shares = int((self.Portfolio.TotalPortfolioValue * 0.40) // today_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_closes.IsReady and self.aapl_rsi.IsReady:
            close = self.aapl_closes[0]
            red_three_days = (
                self.aapl_closes[0] < self.aapl_closes[1] and
                self.aapl_closes[1] < self.aapl_closes[2] and
                self.aapl_closes[2] < self.aapl_closes[3]
            )

            if red_three_days and self.Portfolio.Cash >= 20_000:
                shares = int(20_000 // close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares
